package com.lifeorganizer;
import javafx.geometry.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import java.sql.*;import java.time.*;import java.io.*;
public class ExpenseAnalyticsView extends VBox {
 private final int userId;private final Label total=new Label();private final PieChart pie=new PieChart();private final BarChart<String,Number> monthly=new BarChart<>(new CategoryAxis(),new NumberAxis());private final TextArea report=new TextArea();
 public ExpenseAnalyticsView(int id){userId=id;setSpacing(12);setPadding(new Insets(18));Label h=new Label("Expenses, Budgets & Reports");h.setStyle("-fx-font-size:25px;-fx-font-weight:bold;-fx-text-fill:#17324d;");Button refresh=new Button("Refresh charts"),budget=new Button("Set monthly budget"),export=new Button("Export report CSV");refresh.setOnAction(e->load());budget.setOnAction(e->setBudget());export.setOnAction(e->export());pie.setTitle("Spending by category (current month)");monthly.setTitle("Monthly spending (last 6 months)");monthly.setLegendVisible(false);report.setEditable(false);report.setPrefRowCount(9);getChildren().addAll(h,new HBox(8,refresh,budget,export),total,new HBox(15,pie,monthly),new Label("Budget status and report"),report);load();}
 private void load(){pie.getData().clear();monthly.getData().clear();String month=YearMonth.now().atDay(1).toString();double sum=0;StringBuilder text=new StringBuilder("MONTHLY BUDGET STATUS\n");try(Connection c=Db.connect()){
  try(PreparedStatement p=c.prepareStatement("SELECT category,SUM(amount) FROM expenses WHERE user_id=? AND expense_date>=? AND expense_date<? GROUP BY category ORDER BY 2 DESC")){p.setInt(1,userId);p.setDate(2,Date.valueOf(month));p.setDate(3,Date.valueOf(YearMonth.now().plusMonths(1).atDay(1)));try(ResultSet r=p.executeQuery()){while(r.next()){double v=r.getDouble(2);sum+=v;pie.getData().add(new PieChart.Data(r.getString(1),v));}}}
  total.setText(String.format("Current month spending: ₹%.2f",sum));
  XYChart.Series<String,Number>s=new XYChart.Series<>();for(int i=5;i>=0;i--){YearMonth m=YearMonth.now().minusMonths(i);double v=0;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND expense_date>=? AND expense_date<?")){p.setInt(1,userId);p.setDate(2,Date.valueOf(m.atDay(1)));p.setDate(3,Date.valueOf(m.plusMonths(1).atDay(1)));try(ResultSet r=p.executeQuery()){if(r.next())v=r.getDouble(1);}}s.getData().add(new XYChart.Data<>(m.toString(),v));}monthly.getData().add(s);
  try(PreparedStatement p=c.prepareStatement("SELECT b.category,b.budget_amount,COALESCE((SELECT SUM(e.amount) FROM expenses e WHERE e.user_id=b.user_id AND e.category=b.category AND e.expense_date>=b.month_start AND e.expense_date<DATE_ADD(b.month_start,INTERVAL 1 MONTH)),0) spent FROM expense_budgets b WHERE b.user_id=? AND b.month_start=? ORDER BY b.category")){p.setInt(1,userId);p.setDate(2,Date.valueOf(YearMonth.now().atDay(1)));try(ResultSet r=p.executeQuery()){while(r.next()){double spent=r.getDouble(3),limit=r.getDouble(2);text.append(String.format("%s: budget ₹%.2f | spent ₹%.2f | remaining ₹%.2f %s%n",r.getString(1),limit,spent,limit-spent,spent>limit?"OVER BUDGET":""));}}}
  if(text.toString().equals("MONTHLY BUDGET STATUS\n"))text.append("No budgets set for this month. Use Set monthly budget.");report.setText(text.toString());
 }catch(Exception e){report.setText("Could not load analytics: "+e.getMessage()+"\nRun database/upgrade_all.sql first.");}}
 private void setBudget(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Set monthly budget");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);GridPane g=new GridPane();g.setPadding(new Insets(12));g.setHgap(8);g.setVgap(8);TextField cat=new TextField(),amount=new TextField();ComboBox<String> month=new ComboBox<>();month.getItems().add(YearMonth.now().toString());month.getSelectionModel().selectFirst();g.addRow(0,new Label("Category"),cat);g.addRow(1,new Label("Monthly amount (₹)"),amount);g.addRow(2,new Label("Month"),month);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(bt->{if(bt==save)try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("INSERT INTO expense_budgets(user_id,category,month_start,budget_amount) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE budget_amount=VALUES(budget_amount)")){p.setInt(1,userId);p.setString(2,cat.getText().trim());p.setDate(3,Date.valueOf(YearMonth.parse(month.getValue()).atDay(1)));p.setBigDecimal(4,new java.math.BigDecimal(amount.getText()));if(cat.getText().isBlank())throw new IllegalArgumentException("Category required");p.executeUpdate();load();}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Budget not saved: "+ex.getMessage()).showAndWait();}});}
 private void export(){FileChooser fc=new FileChooser();fc.setInitialFileName("expense-report.csv");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV","*.csv"));File f=fc.showSaveDialog(getScene().getWindow());if(f==null)return;try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("SELECT expense_date,category,amount,notes FROM expenses WHERE user_id=? ORDER BY expense_date DESC")){p.setInt(1,userId);try(ResultSet r=p.executeQuery();PrintWriter w=new PrintWriter(f)){w.println("date,category,amount,notes");while(r.next())w.printf("%s,\"%s\",%s,\"%s\"%n",r.getDate(1),r.getString(2).replace("\"","\"\""),r.getBigDecimal(3),java.util.Objects.toString(r.getString(4),"").replace("\"","\"\""));}}catch(Exception e){new Alert(Alert.AlertType.ERROR,"Export failed: "+e.getMessage()).showAndWait();}}
}
